do { try await db.save(record) }
catch let error as CKError where error.code == .serverRecordChanged {
    let server = error.userInfo[CKRecordChangedErrorServerRecordKey] as! CKRecord
    server["balance"] = record["balance"]      // merge into the SERVER copy
    try await db.save(server)                  // retry with a fresh change tag
}

